const courses = [
    { id: 1, title: 'Human-Centered Product Design', category: 'DESIGN STUDIO', description: 'Turn field insight into products people can use and trust.', progress: 62, lessons: 5, completed: 3, art: 'art-one', enrolled: true },
    { id: 2, title: 'Data Literacy for Decisions', category: 'FOUNDATIONS', description: 'Read the signal in everyday data and make better calls.', progress: 28, lessons: 6, completed: 2, art: 'art-two', enrolled: true },
    { id: 3, title: 'Systems Thinking 101', category: 'NEW THIS WEEK', description: 'See the relationships behind complex problems.', progress: 0, lessons: 4, completed: 0, art: 'art-three', enrolled: false }
];
const lessons = [
    { id: 1, title: 'The empathy loop', duration: '12 min', complete: true, content: 'Empathy is not a personality trait. It is a repeatable practice: observe, listen, frame, and test. The loop helps a team turn a person’s lived experience into a useful design question.' },
    { id: 2, title: 'From insight to opportunity', duration: '18 min', complete: true, content: 'A strong insight connects a real behavior to a meaningful need. Opportunity statements keep the team curious: they describe who needs what and why, without jumping to a solution too early.' },
    { id: 3, title: 'Mapping the learning journey', duration: '15 min', complete: false, content: 'Journey maps make an experience visible across time. Mark the learner’s goal, actions, emotions and barriers, then look for moments where a small change could create a large improvement.' },
    { id: 4, title: 'Prototype with intention', duration: '22 min', complete: false, content: 'A prototype is a question made tangible. Choose the smallest representation that can produce useful evidence, define what you are testing, and make the next decision visible.' }
];
const submissions = [
    { learner: 'Minh Anh', initials: 'MA', assignment: 'Journey map critique', submitted: '28 Aug, 09:12', status: 'submitted', grade: '', feedback: '' },
    { learner: 'Quang Huy', initials: 'QH', assignment: 'Journey map critique', submitted: '27 Aug, 18:44', status: 'graded', grade: '8.5 / 10', feedback: 'Strong observation layer. Add one more opportunity backed by evidence.' },
    { learner: 'Linh Chi', initials: 'LC', assignment: 'Journey map critique', submitted: 'Not submitted', status: 'missing', grade: '', feedback: '' }
];
const state = { screen: 'login', role: 'learner', courseId: 1, lessonId: 3, tutorOpen: false, tutorMessages: [], selectedSubmission: 0, lateDemo: false, toast: '' };
const app = document.querySelector('#app');
const course = () => courses.find(item => item.id === state.courseId);
const lesson = () => lessons.find(item => item.id === state.lessonId);
function esc(value) { return String(value).replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[char])); }
function toast(message) { state.toast = message; render(); setTimeout(() => { state.toast = ''; render(); }, 2500); }
function go(screen) { state.screen = screen; state.tutorOpen = false; render(); }
function login(role) { state.role = role; state.screen = role === 'learner' ? 'dashboard' : 'instructor'; render(); }
function enrollCourse(courseId) { const item = courses.find(entry => entry.id === courseId); item.enrolled = true; toast(`Enrolled in ${item.title}`); }
function navButton(screen, label, icon) { return `<button class="${state.screen === screen ? 'active' : ''}" onclick="go('${screen}')">${icon} &nbsp;${label}</button>`; }
function shell(content) {
    const instructor = state.role === 'instructor';
    return `<div class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">✦</span> orbit<span style="color:var(--coral)">.</span></div><div><div class="nav-label">Workspace</div><nav class="nav">${instructor ? navButton('instructor', 'Instructor home', '▦') + navButton('review', 'Submissions', '✓') : navButton('dashboard', 'My dashboard', '▦') + navButton('courses', 'Course library', '◈') + navButton('course', 'Current course', '→') + navButton('states', 'State lab', '◇')}</nav></div><div class="sidebar-footer">Prototype mode<br><span style="color:#dbe5ef">Sample workspace</span></div></aside><main class="main"><header class="topbar"><small>${instructor ? 'Instructor workspace' : 'Learner workspace'} / prototype</small><div class="profile"><span>${instructor ? 'Dr. Sarah Nguyen' : 'Alex Tran'}</span><span class="avatar">${instructor ? 'SN' : 'AT'}</span></div></header>${content}</main></div>${state.toast ? `<div class="toast">${state.toast}</div>` : ''}`;
}
function loginView() { return `<div class="login"><div class="login-card"><div class="brand"><span class="brand-mark">✦</span> orbit<span style="color:var(--coral)">.</span></div><span class="eyebrow">AI learning management system</span><h1>Make learning<br>move forward.</h1><p>Prototype access · use a sample role to explore the critical flows.</p><div class="role-picker"><button class="${state.role === 'learner' ? 'selected' : ''}" onclick="state.role='learner';render()">Learner<br><small class="muted">Learn and submit</small></button><button class="${state.role === 'instructor' ? 'selected' : ''}" onclick="state.role='instructor';render()">Instructor<br><small class="muted">Review and grade</small></button></div><button class="btn primary" style="width:100%" onclick="login(state.role)">Continue to workspace →</button><p style="font-size:12px;margin-top:24px">Sample data only · no backend connection</p></div></div>`; }
function dashboard() { return shell(`<section class="content"><div class="page-head"><div><span class="eyebrow">Thursday, 28 August</span><h1>Good morning, Alex.</h1><p>Pick up where your curiosity left off.</p></div><div class="actions"><button class="btn ghost" onclick="go('courses')">Browse courses</button></div></div><div class="stat-row"><div class="card stat"><strong>62%</strong><span>Current course progress</span><div class="progress"><span style="width:62%"></span></div></div><div class="card stat"><strong>03</strong><span>Lessons completed</span><div class="progress"><span style="width:60%"></span></div></div><div class="card stat"><strong>01</strong><span>Assignment due soon</span><p class="muted" style="margin:7px 0 0">Due 30 Aug · 23:59</p></div></div><div class="page-head" style="margin-bottom:16px"><h2>Continue learning</h2><span class="badge teal">2 enrolled courses</span></div><div class="grid two">${courseCard(courses[0], true)}${courseCard(courses[1], true)}</div></section>`); }
function courseCard(item, enrolled) { return `<article class="card course-card"><div class="course-art ${item.art}">${item.category}</div><div class="course-body"><h3>${item.title}</h3><p>${item.description}</p><div class="meta"><span>${item.lessons} lessons</span><span>${enrolled ? `${item.progress}% complete` : 'Not enrolled'}</span></div>${enrolled ? `<div class="progress"><span style="width:${item.progress}%"></span></div>` : ''}<button class="btn small ${enrolled ? 'primary' : 'ghost'}" style="margin-top:15px" onclick="state.courseId=${item.id};go('course')">${enrolled ? 'Open course →' : 'View course'}</button></div></article>`; }
function coursesView() { return shell(`<section class="content"><div class="page-head"><div><span class="eyebrow">Explore</span><h1>Course library</h1><p>Build a learning path that fits your next step.</p></div><span class="badge">3 courses</span></div><div class="grid three">${courses.map(item => courseCard(item, item.enrolled)).join('')}</div></section>`); }
function courseView() { const item = course(); if (!item.enrolled) return shell(`<section class="content"><div class="page-head"><div><span class="eyebrow">Course detail · ${item.category}</span><h1>${item.title}</h1><p>${item.description}</p></div><span class="badge">Not enrolled</span></div><div class="card"><h2>Ready to begin?</h2><p class="muted">Enroll to unlock the Lessons and Assignments in this Course.</p><button class="btn primary" onclick="enrollCourse(${item.id})">Enroll in course →</button></div></section>`); return shell(`<section class="content"><div class="page-head"><div><span class="eyebrow">Course detail · ${item.category}</span><h1>${item.title}</h1><p>${item.description}</p></div><span class="badge teal">Enrolled</span></div><div class="card" style="margin-bottom:22px"><div class="meta"><strong>Learning progress</strong><strong>${item.progress}%</strong></div><div class="progress"><span style="width:${item.progress}%"></span></div><span class="muted">${item.completed} of ${item.lessons} lessons complete · 1 assignment remaining</span></div><div class="detail-layout"><div class="card"><h2>Course content</h2><p class="muted">A practical sequence for building better learning experiences.</p><div class="lesson-list">${lessons.map((item, index) => `<div class="list-item"><div class="item-title"><span class="item-icon">${item.complete ? '✓' : String(index + 1).padStart(2, '0')}</span><span>${item.title}<small class="muted" style="display:block;font-weight:400">Lesson · ${item.duration}</small></span></div><button class="btn small ${item.complete ? 'ghost' : 'primary'}" onclick="state.lessonId=${item.id};go('lesson')">${item.complete ? 'Review' : 'Start lesson'}</button></div>`).join('')}<div class="list-item"><div class="item-title"><span class="item-icon" style="background:var(--coral-soft);color:var(--coral)">✎</span><span>Journey map critique<small class="muted" style="display:block;font-weight:400">Assignment · Due 30 Aug, 23:59</small></span></div><button class="btn small coral" onclick="go('assignment')">Open assignment</button></div></div></div><div class="stack"><div class="card"><h3>Next up</h3><p><strong>Mapping the learning journey</strong></p><p class="muted">15 min · Lesson 03</p><button class="btn primary small" onclick="state.lessonId=3;go('lesson')">Continue →</button></div><div class="card"><h3>Assignment status</h3><p class="muted">Journey map critique</p><span class="badge coral">Incomplete</span><p class="muted" style="font-size:13px">Deadline in 2 days</p></div></div></div></section>`); }
function lessonView() { const item = lesson(); return shell(`<section class="content"><div class="page-head"><div><span class="eyebrow">${course().title} / Lesson ${String(item.id).padStart(2, '0')}</span><h1>${item.title}</h1><p>${item.duration} read · ${item.complete ? 'Completed' : 'In progress'}</p></div><div class="actions"><button class="btn coral" onclick="state.tutorOpen=true;render()">✦ Ask AI Tutor</button></div></div><div class="detail-layout"><article class="card lesson-copy"><span class="badge ${item.complete ? 'teal' : 'gold'}">${item.complete ? 'Lesson completed' : 'In progress'}</span><h2 style="margin-top:20px">A map is a conversation starter.</h2><p>${item.content}</p><p>The point is not to document every interaction. It is to create a shared view of the moments that matter, so the team can make a thoughtful choice about what to improve next.</p><blockquote>“When the whole experience is visible, the next useful question becomes easier to ask.”</blockquote><p>${item.complete ? 'You have completed this lesson. Revisit it anytime from the course outline.' : 'Read through the lesson, then mark it complete to update your learning progress.'}</p><div class="actions" style="margin-top:28px">${item.complete ? '<button class="btn ghost" onclick="go(\'course\')">Back to course</button>' : '<button class="btn primary" onclick="completeLesson()">Mark as complete ✓</button>'}</div></article><aside class="stack side-panel"><div class="card"><h3>In this course</h3><div class="progress"><span style="width:62%"></span></div><strong>62% complete</strong><div class="lesson-list">${lessons.map((entry, index) => `<button class="list-item" style="background:${entry.id === item.id ? '#f0f8f6' : '#fff'};border:0;text-align:left" onclick="state.lessonId=${entry.id};render()"><span>${entry.complete ? '✓' : String(index + 1).padStart(2, '0')} &nbsp;${entry.title}</span><small class="muted">${entry.duration}</small></button>`).join('')}</div></div>${state.tutorOpen ? tutorPanel() : '<div class="card"><h3>Need a nudge?</h3><p class="muted">Ask about this lesson without leaving your learning path.</p><button class="btn small coral" onclick="state.tutorOpen=true;render()">Open AI Tutor</button></div>'}</aside></div></section>`); }
function tutorPanel() { return `<div class="card tutor"><div class="meta"><h3>AI Tutor</h3><button class="btn small ghost" onclick="state.tutorOpen=false;render()">Close</button></div><p class="muted" style="font-size:13px">Context: ${lesson().title}</p><div class="chat">${state.tutorMessages.length ? state.tutorMessages.map(message => `<div class="message ${message.user ? 'user' : ''}">${esc(message.text)}${message.source ? `<span class="source">Source · ${esc(message.source)}</span>` : ''}</div>`).join('') : '<div class="message">Hi Alex. Ask me about the lesson and I will stay within its context.</div>'}</div><div class="actions"><input id="tutor-input" placeholder="Ask about this lesson..." onkeydown="if(event.key==='Enter') askTutor()"><button class="btn coral" onclick="askTutor()">Send</button></div><button class="btn small ghost" style="margin-top:10px" onclick="askOutside()">Try insufficient context</button></div>`; }
function assignmentView() { return shell(`<section class="content"><div class="page-head"><div><span class="eyebrow">${course().title} / Assignment</span><h1>Journey map critique</h1><p>Show what you notice, then explain why it matters.</p></div><span class="badge gold">Due 30 Aug, 23:59</span></div><div class="detail-layout"><div class="stack"><div class="card"><h2>Assignment brief</h2><p>Choose one learning experience you know. Map the learner’s goal, actions, emotions and barriers across at least five moments. Identify one opportunity and support it with an observation from your map.</p><div class="alert" style="margin-top:20px">Tip: use the Lesson “Mapping the learning journey” as your starting point.</div></div><div class="card"><h3>Your submission</h3><p class="muted">Text response · sample input</p><textarea id="answer" placeholder="Start writing your critique here...">The learner hesitates when the next step is unclear. I would test a clearer progress signal at that moment.</textarea><div class="actions" style="margin-top:16px"><button class="btn primary" onclick="submitAssignment()">Submit assignment →</button><button class="btn ghost" onclick="state.lateDemo=true;submitAssignment()">Demo late submission</button></div></div></div><aside class="card side-panel"><h3>Assignment details</h3><div class="deadline"><span class="muted">Deadline</span><strong>30 Aug, 23:59</strong></div><div class="deadline"><span class="muted">Attempts</span><strong>1 of 3</strong></div><div class="deadline"><span class="muted">Status</span><span class="badge coral">Incomplete</span></div><p class="muted" style="font-size:13px">Submit again is available before the deadline when allowed.</p></aside></div></section>`); }
function resultView() { const late = state.lateDemo; return shell(`<section class="content"><div class="page-head"><div><span class="eyebrow">Submission result</span><h1>${late ? 'Submitted after the deadline.' : 'Your work is in.'}</h1><p>Journey map critique · ${late ? '28 Aug, 23:59' : '28 Aug, 09:12'}</p></div><span class="badge ${late ? 'gold' : 'teal'}">${late ? 'Late submission' : 'Submitted'}</span></div><div class="grid two"><div class="card"><div class="alert ${late ? 'warn' : ''}">${late ? 'This submission was received after the deadline and is marked Late.' : 'Submission received successfully. Your instructor will review it.'}</div><div class="deadline"><span class="muted">Status</span><strong>${late ? 'Late' : 'Submitted'}</strong></div><div class="deadline"><span class="muted">Submitted at</span><strong>${late ? '28 Aug, 23:59' : '28 Aug, 09:12'}</strong></div><button class="btn ghost small" style="margin-top:20px" onclick="go('course')">Back to course</button>${!late ? '<button class="btn primary small" style="margin:20px 0 0 7px" onclick="go(\'assignment\')">Submit again</button>' : ''}</div><div class="card"><h3>What happens next</h3><p class="muted">Your Instructor will grade this submission and leave feedback here.</p><span class="badge">Awaiting grade</span></div></div></section>`); }
function instructorView() { return shell(`<section class="content"><div class="page-head"><div><span class="eyebrow">Instructor dashboard</span><h1>Review what learners need next.</h1><p>Track submissions and make feedback useful.</p></div><span class="badge teal">3 learners</span></div><div class="stat-row"><div class="card stat"><strong>2</strong><span>Submissions to review</span></div><div class="card stat"><strong>1</strong><span>Needs follow-up</span></div><div class="card stat"><strong>67%</strong><span>Course submission rate</span></div></div><div class="detail-layout"><div class="card"><div class="meta"><div><h2>Human-Centered Product Design</h2><p class="muted">Journey map critique · due 30 Aug</p></div><span class="badge">3 learners</span></div><div class="submission-list">${submissions.map((item, index) => `<div class="list-item"><div class="item-title"><span class="avatar">${item.initials}</span><span>${item.learner}<small class="muted" style="display:block;font-weight:400">${item.submitted}</small></span></div><div class="actions"><span class="badge ${item.status === 'graded' ? 'teal' : item.status === 'missing' ? 'coral' : 'gold'}">${item.status === 'graded' ? 'Graded' : item.status === 'missing' ? 'Not submitted' : 'Needs review'}</span>${item.status !== 'missing' ? `<button class="btn small primary" onclick="state.selectedSubmission=${index};go('review')">Review</button>` : ''}</div></div>`).join('')}</div></div><div class="card"><h3>Course progress</h3><p class="muted">Learner completion across required items</p><div class="meta"><span>Average progress</span><strong>62%</strong></div><div class="progress"><span style="width:62%"></span></div><p class="muted" style="font-size:13px">One learner has not submitted the current assignment.</p></div></div></section>`); }
function reviewView() { const item = submissions[state.selectedSubmission]; return shell(`<section class="content"><div class="page-head"><div><span class="eyebrow">Submission review / ${item.learner}</span><h1>Journey map critique</h1><p>Submitted ${item.submitted}</p></div><span class="badge gold">Needs review</span></div><div class="detail-layout"><div class="card"><h2>Learner response</h2><p>“The learner hesitates when the next step is unclear. I would test a clearer progress signal at that moment. The map shows that the uncertainty starts after the first activity, where no feedback is visible.”</p><div class="alert" style="margin-top:24px">Submission is linked to Human-Centered Product Design.</div></div><div class="stack side-panel"><div class="card"><h3>Grade & feedback</h3><label for="grade">Grade</label><input id="grade" placeholder="e.g. 8.5 / 10" value="${esc(item.grade)}"><label for="feedback" style="margin-top:15px">Feedback</label><textarea id="feedback" style="min-height:120px" placeholder="Write useful feedback...">${esc(item.feedback)}</textarea><button class="btn primary" style="width:100%;margin-top:14px" onclick="saveGrade()">Save grade & feedback</button></div><div class="card"><h3>Review status</h3><p class="muted">The learner can see grade and feedback after saving.</p><span class="badge">Instructor review</span></div></div></div></section>`); }
function stateLab() { return shell(`<section class="content"><div class="page-head"><div><span class="eyebrow">Prototype QA</span><h1>State lab</h1><p>Visible checkpoints for the required interface states.</p></div><span class="badge">Demo only</span></div><div class="grid three"><div class="card"><span class="badge">default</span><h3 style="margin-top:14px">Ready state</h3><p class="muted">Course content is available and waiting for the next learner action.</p><button class="btn small ghost" onclick="toast('Default state confirmed')">Test interaction</button></div><div class="card"><span class="badge">loading</span><h3 style="margin-top:14px">Loading content</h3><p class="muted">The system is loading the next view.</p><button class="btn small ghost" onclick="toast('Loading...')">Trigger loading</button></div><div class="card"><span class="badge coral">empty</span><h3 style="margin-top:14px">No results</h3><p class="muted">No Course matches the current search.</p><button class="btn small ghost" onclick="toast('No courses found')">Show empty</button></div><div class="card"><span class="badge coral">error</span><h3 style="margin-top:14px">Action failed</h3><p class="muted">Something went wrong while saving. Please try again.</p><button class="btn small ghost" onclick="toast('Error · try again')">Trigger error</button></div><div class="card"><span class="badge coral">permission denied</span><h3 style="margin-top:14px">Restricted content</h3><p class="muted">Enroll in a Course before opening its Lesson.</p><button class="btn small ghost" onclick="state.courseId=3;go('course')">View guard</button></div><div class="card"><span class="badge gold">incomplete</span><h3 style="margin-top:14px">Needs action</h3><p class="muted">Assignment is open and has not been submitted.</p><button class="btn small ghost" onclick="go('assignment')">Open assignment</button></div><div class="card"><span class="badge teal">submitted</span><h3 style="margin-top:14px">Submission success</h3><p class="muted">Submission received and awaiting review.</p><button class="btn small ghost" onclick="state.lateDemo=false;go('result')">View result</button></div><div class="card"><span class="badge gold">late submission</span><h3 style="margin-top:14px">Late result</h3><p class="muted">Submitted after the Deadline and marked Late.</p><button class="btn small ghost" onclick="state.lateDemo=true;go('result')">View late result</button></div><div class="card"><span class="badge teal">graded · feedback available</span><h3 style="margin-top:14px">Instructor result</h3><p class="muted">Grade and Feedback are ready for the Learner.</p><button class="btn small ghost" onclick="state.selectedSubmission=1;go('review')">View feedback</button></div><div class="card"><span class="badge coral">AI Tutor processing</span><h3 style="margin-top:14px">AI states</h3><p class="muted">Processing, answer and insufficient-context are available in Lesson Detail.</p><button class="btn small coral" onclick="state.lessonId=3;state.tutorOpen=true;go('lesson')">Open AI Tutor</button></div></div></section>`); }
function completeLesson() { lessons.find(item => item.id === state.lessonId).complete = true; course().completed = Math.min(course().lessons, course().completed + 1); course().progress = Math.round(course().completed / course().lessons * 100); toast('Lesson completed · progress updated'); }
function submitAssignment() { const answer = document.querySelector('#answer')?.value.trim(); if (!answer) return toast('Add a response before submitting.'); state.screen = 'result'; render(); }
function saveGrade() { const grade = document.querySelector('#grade').value.trim(); const feedback = document.querySelector('#feedback').value.trim(); if (!grade || !feedback) return toast('Add both grade and feedback.'); submissions[state.selectedSubmission].grade = grade; submissions[state.selectedSubmission].feedback = feedback; submissions[state.selectedSubmission].status = 'graded'; toast('Grade and feedback saved'); }
function askTutor() { const input = document.querySelector('#tutor-input'); const question = input?.value.trim(); if (!question) return; state.tutorMessages.push({ user: true, text: question }); render(); setTimeout(() => { state.tutorMessages.push({ text: 'Hãy bắt đầu bằng cách xác định mục tiêu của người học, sau đó ghi lại hành động và rào cản ở từng thời điểm. Một insight tốt nối hành vi quan sát được với một nhu cầu có ý nghĩa.', source: `Lesson ${String(lesson().id).padStart(2, '0')} · ${lesson().title}` }); render(); }, 650); }
function askOutside() { state.tutorMessages.push({ user: true, text: 'Ai sẽ thắng giải bóng đá năm sau?' }, { text: 'KHÔNG ĐỦ DỮ LIỆU', source: 'Context hiện tại · ' + lesson().title }); render(); }
function demoState(type) { state.demoState = type; render(); }
function confirmDemo() { state.demoState = 'success'; render(); }
function stateLab() { const demo = state.demoState; const panels = { loading: ['Loading', 'Đang tải dữ liệu Course...', 'loading'], empty: ['Empty', 'Chưa có Course phù hợp với tìm kiếm.', 'empty'], error: ['Error', 'Không thể tải dữ liệu. Hãy thử lại.', 'error'], permission: ['Permission denied', 'Bạn chưa có quyền truy cập nội dung này.', 'error'], confirmation: ['Confirmation', 'Bạn có chắc muốn Submit Assignment không?', 'warn'], success: ['Success', 'Thao tác đã hoàn tất thành công.', 'success'] }; return shell(`<section class="content"><div class="page-head"><div><span class="eyebrow">Prototype QA</span><h1>State lab</h1><p>Click từng state để kiểm tra feedback hiển thị rõ ràng.</p></div><span class="badge">Required states</span></div><div class="grid three"><div class="card"><span class="badge">default</span><h3 style="margin-top:14px">Ready state</h3><p class="muted">Workspace sẵn sàng cho thao tác tiếp theo.</p><button class="btn small ghost" onclick="demoState('default')">Reset state</button></div>${Object.entries(panels).map(([key, panel]) => `<div class="card"><span class="badge ${panel[2] === 'error' ? 'coral' : panel[2] === 'success' ? 'teal' : panel[2] === 'warn' ? 'gold' : ''}">${panel[0]}</span><h3 style="margin-top:14px">${panel[1]}</h3><p class="muted">${key === 'loading' ? 'Feedback tiến trình được hiển thị ngay trong vùng nội dung.' : key === 'confirmation' ? 'Yêu cầu xác nhận trước critical action.' : 'State có thông báo và hướng xử lý rõ ràng.'}</p><button class="btn small ${key === 'success' ? 'primary' : 'ghost'}" onclick="demoState('${key}')">Test ${panel[0]}</button></div>`).join('')}</div>${demo && demo !== 'default' && panels[demo] ? `<div class="card" style="margin-top:22px"><div class="alert ${panels[demo][2] === 'error' ? 'error' : panels[demo][2] === 'warn' ? 'warn' : ''}"><strong>${panels[demo][0]}:</strong> ${panels[demo][1]}</div><div class="actions" style="margin-top:16px">${demo === 'loading' ? '<button class="btn small ghost" onclick="demoState(\'success\')">Finish loading</button>' : demo === 'error' ? '<button class="btn small primary" onclick="demoState(\'success\')">Retry</button>' : demo === 'permission' ? '<button class="btn small ghost" onclick="go(\'courses\')">Back to courses</button>' : demo === 'confirmation' ? '<button class="btn small ghost" onclick="demoState(\'default\')">Cancel</button><button class="btn small primary" onclick="confirmDemo()">Confirm</button>' : '<button class="btn small ghost" onclick="demoState(\'default\')">Dismiss</button>'}</div></div>` : ''}</section>`); }
function render() { if (state.screen === 'login') app.innerHTML = loginView(); else if (state.screen === 'dashboard') app.innerHTML = dashboard(); else if (state.screen === 'courses') app.innerHTML = coursesView(); else if (state.screen === 'course') app.innerHTML = courseView(); else if (state.screen === 'lesson') app.innerHTML = lessonView(); else if (state.screen === 'assignment') app.innerHTML = assignmentView(); else if (state.screen === 'result') app.innerHTML = resultView(); else if (state.screen === 'instructor') app.innerHTML = instructorView(); else if (state.screen === 'review') app.innerHTML = reviewView(); else if (state.screen === 'states') app.innerHTML = stateLab(); }
render();
